Here's a type-safe implementation that validates the input at runtime and narrows `unknown` to a well-typed `Event`:

```typescript
// ---- Event shape ----
export interface Event<P = Record<string, unknown>> {
  name: string;
  timestamp: Date;
  payload: P;
}

// ---- Error type ----
export class EventParseError extends Error {
  constructor(message: string, public readonly raw: unknown) {
    super(message);
    this.name = "EventParseError";
  }
}

// ---- Helpers ----
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTimestamp(value: unknown, raw: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string" && value.trim() !== "") {
    date = new Date(value); // ISO 8601 string
  } else {
    throw new EventParseError(
      "Event 'timestamp' must be a Date, epoch milliseconds, or ISO string",
      raw
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`Event 'timestamp' is invalid: ${String(value)}`, raw);
  }
  return date;
}

// ---- Parser ----
export function parseEvent(raw: unknown): Event {
  // Accept a JSON string as well as an already-parsed object
  let data: unknown = raw;
  if (typeof raw === "string") {
    try {
      data = JSON.parse(raw);
    } catch {
      throw new EventParseError("Event is not valid JSON", raw);
    }
  }

  if (!isRecord(data)) {
    throw new EventParseError("Event must be an object", raw);
  }

  const { name, timestamp, payload } = data;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("Event 'name' must be a non-empty string", raw);
  }

  const parsedTimestamp = parseTimestamp(timestamp, raw);

  // Missing payload defaults to {}; present payload must be an object
  if (payload !== undefined && !isRecord(payload)) {
    throw new EventParseError("Event 'payload' must be an object", raw);
  }

  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload: payload ?? {},
  };
}
```

**Usage:**

```typescript
const event = parseEvent({
  name: "user.signup",
  timestamp: "2024-05-01T12:00:00Z",
  payload: { userId: 42 },
});
// event: Event → { name: "user.signup", timestamp: Date, payload: { userId: 42 } }

parseEvent('{"name":"ping","timestamp":1714564800000}');
// → payload defaults to {}

try {
  parseEvent({ name: "", timestamp: "nope" });
} catch (e) {
  if (e instanceof EventParseError) console.error(e.message);
  // "Event 'name' must be a non-empty string"
}
```

**Design notes:**

- **No unsafe casts.** Type guards (`isRecord`, `typeof`) narrow `unknown` step by step, so the compiler verifies every field.
- **Flexible timestamps.** It accepts `Date`, epoch milliseconds, or ISO strings, and rejects anything that produces an `Invalid Date`.
- **Custom error class.** Callers can distinguish parse failures from other errors and inspect the original `raw` input.
- **Generic payload.** `Event<P>` lets you specialize the payload type, e.g. `Event<{ userId: number }>`. Note that `parseEvent` only checks that the payload is an object. For per-event payload schemas, a validation library like **Zod** is a good fit:

```typescript
import { z } from "zod";

const EventSchema = z.object({
  name: z.string().min(1),
  timestamp: z.coerce.date(),
  payload: z.record(z.unknown()).default({}),
});

export type Event = z.infer<typeof EventSchema>;
export const parseEvent = (raw: unknown): Event => EventSchema.parse(raw);
```

