```typescript
/** The validated, typed shape of an event. */
export interface Event<TPayload = Record<string, unknown>> {
  name: string;
  timestamp: Date;
  payload: TPayload;
}

/** Thrown when raw input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly raw: unknown) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTimestamp(value: unknown, raw: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    // Accept epoch milliseconds.
    date = new Date(value);
  } else if (typeof value === "string" && value.trim() !== "") {
    // Accept ISO 8601 strings (or numeric strings as epoch ms).
    const asNumber = Number(value);
    date = Number.isFinite(asNumber) ? new Date(asNumber) : new Date(value);
  } else {
    throw new EventParseError(
      `"timestamp" must be a Date, epoch number, or ISO string; got ${typeof value}`,
      raw
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`"timestamp" is not a valid date: ${String(value)}`, raw);
  }
  return date;
}

/**
 * Parses an untrusted value into a typed Event.
 * Accepts either an object or a JSON string.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  let data: unknown = raw;

  if (typeof raw === "string") {
    try {
      data = JSON.parse(raw);
    } catch {
      throw new EventParseError("Input string is not valid JSON", raw);
    }
  }

  if (!isRecord(data)) {
    throw new EventParseError("Event must be a non-null object", raw);
  }

  const { name, timestamp, payload } = data;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(`"name" must be a non-empty string`, raw);
  }

  // Treat a missing payload as empty; reject non-object payloads.
  if (payload !== undefined && !isRecord(payload)) {
    throw new EventParseError(`"payload" must be an object if provided`, raw);
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp, raw),
    payload: payload ?? {},
  };
}
```

### Usage

```typescript
const event = parseEvent({
  name: "user.signup",
  timestamp: "2024-05-01T12:00:00Z",
  payload: { userId: 42 },
});
event.timestamp.toISOString(); // "2024-05-01T12:00:00.000Z"

parseEvent('{"name":"ping","timestamp":1714564800000}');
// → { name: "ping", timestamp: Date, payload: {} }

try {
  parseEvent({ name: "", timestamp: "nope" });
} catch (err) {
  if (err instanceof EventParseError) console.error(err.message);
  // → "name" must be a non-empty string
}
```

### Design notes

- **Runtime validation:** TypeScript types disappear at runtime, so every field is checked explicitly rather than cast with `as Event`.
- **Flexible timestamps:** Accepts `Date`, epoch milliseconds, or ISO strings, and normalizes all of them to a `Date`. Invalid dates are rejected.
- **Custom error type:** `EventParseError` keeps the original `raw` input for debugging and lets callers distinguish parse failures from other errors.
- **Generic payload:** `Event<TPayload>` defaults to `Record<string, unknown>`. To get a strongly typed payload, validate it further (or use a schema library like Zod) and narrow it to something like `Event<{ userId: number }>`.

If you'd prefer a non-throwing API, you can wrap this to return a result type such as `{ ok: true; event: Event } | { ok: false; error: string }`.

