# Parsing an `Event` from Unknown Input

The `Event` type is declared first. `parseEvent` then validates the raw input step by step. It returns a fully typed `Event` or throws a descriptive error.

```typescript
/** The shape of a validated event. */
export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

/** Thrown when raw input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string" && value.trim() !== "") {
    date = new Date(value); // ISO 8601 or other Date-parseable string
  } else {
    throw new EventParseError(
      `"timestamp" must be a Date, epoch milliseconds, or date string; got ${typeof value}`
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`"timestamp" is not a valid date: ${String(value)}`);
  }
  return date;
}

/**
 * Parses an unknown value into a typed Event.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("Event must be a non-null object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError(`"name" must be a non-empty string`);
  }

  const parsedTimestamp = parseTimestamp(timestamp);

  let parsedPayload: Record<string, unknown>;
  if (payload === undefined) {
    parsedPayload = {};
  } else if (isPlainObject(payload)) {
    parsedPayload = payload;
  } else {
    throw new EventParseError(`"payload" must be an object if provided`);
  }

  return {
    name: name.trim(),
    timestamp: parsedTimestamp,
    payload: parsedPayload,
  };
}
```

## Usage

```typescript
const event = parseEvent(JSON.parse(
  '{"name":"user.signup","timestamp":"2024-05-01T12:00:00Z","payload":{"userId":42}}'
));
