## Event type and parser

```typescript
/** A validated, normalized event. */
export interface Event {
  /** Non-empty event name, e.g. "user.signed_up". */
  name: string;
  /** Moment the event occurred. */
  timestamp: Date;
  /** Arbitrary JSON-like data attached to the event. */
  payload: Record<string, unknown>;
}

/** Thrown when input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly path: string) {
    super(`${path}: ${message}`);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    // Heuristic: values below 1e12 are treated as seconds, otherwise milliseconds.
    date = new Date(value < 1e12 ? value * 1000 : value);
  } else if (typeof value === "string" && value.trim() !== "") {
    const trimmed = value.trim();
    date = /^\d+$/.test(trimmed)
      ? parseTimestamp(Number(trimmed))
      : new Date(trimmed);
  } else {
    throw new EventParseError(
      "expected a Date, epoch number, or ISO-8601 string",
      "timestamp"
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError("is not a valid date", "timestamp");
  }
  return date;
}

/**
 * Validates untrusted input and returns a typed Event.
 * Accepts either an object or a JSON string encoding one.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  let input: unknown = raw;

  if (typeof input === "string") {
    try {
      input = JSON.parse(input);
    } catch {
      throw new EventParseError("is not valid JSON", "$");
    }
  }

  if (!isPlainObject(input)) {
    throw new EventParseError("expected an object", "$");
  }

  const { name, timestamp, payload } = input;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("expected a non-empty string", "name");
  }

  let parsedPayload: Record<string, unknown>;
  if (payload === undefined || payload === null) {
    parsedPayload = {};
  } else if (isPlainObject(payload)) {
    parsedPayload = payload;
  } else {
    throw new EventParseError("expected an object", "payload");
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp),
    payload: parsedPayload,
  };
}
```

