If you'd prefer a non-throwing API, wrap the call so it returns `{ ok: true, value } | { ok: false, error }`. If your project already uses Zod, the equivalent is roughly `z.object({ name: z.string().min(1), timestamp: z.coerce.date(), payload: z.record(z.unknown()).default({}) })`.

Here's a type-safe implementation that validates untrusted input before returning a typed `Event`:

```typescript
export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string" && value.trim() !== "") {
    date = new Date(value); // ISO 8601 or other Date-parsable string
  } else {
    throw new EventParseError(
      "timestamp must be a Date, epoch milliseconds, or a date string"
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`timestamp is not a valid date: ${String(value)}`);
  }
  return date;
}

export function parseEvent(raw: unknown): Event {
  // Accept a JSON string as a convenience
  let input: unknown = raw;
  if (typeof raw === "string") {
    try {
      input = JSON.parse(raw);
    } catch {
      throw new EventParseError("raw input is a string but not valid JSON");
    }
  }

  if (!isPlainObject(input)) {
    throw new EventParseError("event must be an object");
  }

  const { name, timestamp, payload } = input;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("name must be a non-empty string");
  }

  const parsedPayload = payload ?? {};
  if (!isPlainObject(parsedPayload)) {
    throw new EventParseError("payload must be an object if provided");
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp),
    payload: { ...parsedPayload },
  };
}
```

**Usage:**

```typescript
const evt = parseEvent({
  name: "user.signup",
  timestamp: "2024-05-01T12:00:00Z",
  payload: { userId: 42 },
});
// evt.timestamp is a Date, evt.payload is Record<string, unknown>

parseEvent('{"name":"ping","timestamp":1714564800000}');
// -> { name: "ping", timestamp: Date, payload: {} }

parseEvent({ name: "", timestamp: 0 });
// throws EventParseError: name must be a non-empty string
```

**Design notes:**
- **`unknown` input → narrowed output**: every field is checked with type guards, so no `as` casts are needed.
- **Timestamp normalization**: accepts `Date`, epoch ms, or date strings, and always returns a valid `Date` (rejects `Invalid Date`).
- **Payload**: optional, defaults to `{}`, and is shallow-copied so callers can't mutate the original input through the result.
- **Custom error class**: lets callers distinguish parse failures with `instanceof EventParseError`.

If you want a strongly typed payload per event name, you could make it generic, e.g. `Event<T = Record<string, unknown>>`, and pair it with a schema library like Zod for per-event payload validation.

Here's a self-contained implementation with no dependencies. It validates the input at runtime, so the returned value is guaranteed to match the declared type.

```typescript
/** The shape of a validated event. */
export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

/** Thrown when raw input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly field?: keyof Event) {
    super(field ? `Invalid event.${field}: ${message}` : `Invalid event: ${message}`);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime()); // defensive copy
  } else if (typeof value === "number") {
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string" && value.trim() !== "") {
    date = new Date(value); // ISO 8601 or other Date-parsable string
  } else {
    throw new EventParseError(
      "expected a Date, epoch milliseconds, or date string",
      "timestamp",
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`could not parse ${JSON.stringify(value)} as a date`, "timestamp");
  }
  return date;
}

/**
 * Parses an untrusted value (e.g. from JSON.parse) into a typed Event.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("expected an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("expected a non-empty string", "name");
  }

  // Treat a missing payload as empty, but reject non-object values.
  let parsedPayload: Record<string, unknown>;
  if (payload === undefined) {
    parsedPayload = {};
  } else if (isPlainObject(payload)) {
    parsedPayload = payload;
  } else {
    throw new EventParseError("expected a plain object", "payload");
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp),
    payload: parsedPayload,
  };
}
```

### Usage

```typescript
const event = parseEvent(JSON.parse(`{
  "name": "user.signup",
  "timestamp": "2024-05-01T12:00:00Z",
  "payload": { "userId": 42 }
}`));

event.timestamp.getFullYear(); // 2024, fully typed

try {
  parseEvent({ name: "", timestamp: "nope" });
} catch (err) {
  if (err instanceof EventParseError) {
    console.error(err.message); // "Invalid event.name: expected a non-empty string"
  }
}
```

### Design notes

- **`unknown` input, not `any`**: This forces the function to narrow every field before using it, so the compiler checks the validation logic.
- **Flexible timestamps**: The function accepts `Date`, epoch milliseconds, or date strings, then normalizes them to a `Date`. Invalid dates (`NaN`) are rejected.
- **Plain-object check**: The payload must be a plain object. Arrays, `null`, class instances, and `Date` values are rejected.
- **Missing payload becomes `{}`**: If you'd rather require a payload, remove the `undefined` branch.
- **Typed errors**: `EventParseError.field` tells callers which field failed.

If you prefer not to throw, you can wrap the function in a result type:

```typescript
type ParseResult = { ok: true; event: Event } | { ok: false; error: EventParseError };

export function safeParseEvent(raw: unknown): ParseResult {
  try {
    return { ok: true, event: parseEvent(raw) };
  } catch (e) {
    if (e instanceof EventParseError) return { ok: false, error: e };
    throw e;
  }
}
```

If your project already uses a schema library, `zod` expresses the same thing in a few lines: `z.object({ name: z.string().min(1), timestamp: z.coerce.date(), payload: z.record(z.unknown()).default({}) })`.

Here's a type-safe implementation that validates untrusted input at runtime and narrows it to a typed `Event`:

```typescript
/** JSON-compatible payload value. */
export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

/** The shape of a parsed event. */
export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, JsonValue>;
}

/** Thrown when raw input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly path?: string) {
    super(path ? `${path}: ${message}` : message);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

function isJsonValue(value: unknown, seen = new WeakSet<object>()): value is JsonValue {
  if (value === null) return true;
  switch (typeof value) {
    case "string":
    case "boolean":
      return true;
    case "number":
      return Number.isFinite(value);
    case "object": {
      if (seen.has(value)) return false; // reject circular structures
      seen.add(value);
      if (Array.isArray(value)) return value.every((v) => isJsonValue(v, seen));
      if (isPlainObject(value)) return Object.values(value).every((v) => isJsonValue(v, seen));
      return false;
    }
    default:
      return false; // undefined, function, symbol, bigint
  }
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string" && value.trim() !== "") {
    date = new Date(value); // ISO 8601 recommended
  } else {
    throw new EventParseError(
      "must be a Date, epoch milliseconds, or ISO 8601 string",
      "timestamp"
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`invalid date value ${JSON.stringify(value)}`, "timestamp");
  }
  return date;
}

/**
 * Parses untrusted input into a typed Event.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("event must be a plain object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("must be a non-empty string", "name");
  }

  const parsedPayload = payload === undefined ? {} : payload;
  if (!isPlainObject(parsedPayload) || !isJsonValue(parsedPayload)) {
    throw new EventParseError("must be a JSON-serializable object", "payload");
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp),
    payload: parsedPayload as Record<string, JsonValue>,
  };
}
```

### Usage

```typescript
const event = parseEvent(JSON.parse(
  '{"name":"user.signup","timestamp":"2024-05-01T12:00:00Z","payload":{"userId":42}}'
));
console.log(event.name);                   // "user.signup"
console.log(event.timestamp.toISOString()); // "2024-05-01T12:00:00.000Z"

try {
  parseEvent({ name: "", timestamp: "nope" });
} catch (err) {
  if (err instanceof EventParseError) console.error(err.message); // "name: must be a non-empty string"
}
```

### Design notes

- **`unknown` input**: forces explicit narrowing; no `any` leaks through.
- **Timestamp flexibility**: accepts `Date`, epoch ms, or ISO strings, normalized to a `Date` and rejecting invalid dates (`new Date("nope")` doesn't throw on its own).
- **Payload safety**: restricted to JSON-compatible values, rejecting functions, class instances, `NaN`/`Infinity`, and circular references. A missing payload defaults to `{}`.
- **Errors**: a dedicated `EventParseError` with a field path makes failures easy to catch and report.

If you want a generic payload type, you could make it `Event<P = Record<string, JsonValue>>` and accept a validator function, or use a schema library like Zod (`z.object({ name: z.string().min(1), timestamp: z.coerce.date(), payload: z.record(z.unknown()) })`) for less hand-written code.

Here's a self-contained implementation. It validates the input at runtime, so the returned value really matches the `Event` type instead of just being cast to it.

```ts
/**
 * Shape of a parsed event.
 * `P` lets callers narrow the payload type when they supply a validator.
 */
export interface Event<P = unknown> {
  name: string;
  timestamp: Date;
  payload: P;
}

/** Thrown when the raw input can't be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly path: string) {
    super(`${path}: ${message}`);
    this.name = "EventParseError";
  }
}

/** Optional payload validator: returns the typed payload or throws. */
export type PayloadParser<P> = (raw: unknown) => P;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime()); // defensive copy
  } else if (typeof value === "number") {
    // Accepts epoch milliseconds.
    date = new Date(value);
  } else if (typeof value === "string" && value.trim() !== "") {
    // Accepts ISO 8601 strings (and numeric strings as epoch ms).
    const asNumber = Number(value);
    date = Number.isFinite(asNumber) ? new Date(asNumber) : new Date(value);
  } else {
    throw new EventParseError(
      "expected a Date, epoch milliseconds, or ISO date string",
      "timestamp"
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`invalid date value ${JSON.stringify(value)}`, "timestamp");
  }
  return date;
}

export function parseEvent(raw: unknown): Event<unknown>;
export function parseEvent<P>(raw: unknown, parsePayload: PayloadParser<P>): Event<P>;
export function parseEvent<P>(
  raw: unknown,
  parsePayload?: PayloadParser<P>
): Event<P | unknown> {
  // Allow JSON strings as a convenience.
  if (typeof raw === "string") {
    try {
      raw = JSON.parse(raw);
    } catch {
      throw new EventParseError("input string is not valid JSON", "$");
    }
  }

  if (!isRecord(raw)) {
    throw new EventParseError("expected an object", "$");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("expected a non-empty string", "name");
  }

  if (!("payload" in raw)) {
    throw new EventParseError("missing required field", "payload");
  }

  let typedPayload: P | unknown = payload;
  if (parsePayload) {
    try {
      typedPayload = parsePayload(payload);
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err);
      throw new EventParseError(reason, "payload");
    }
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp),
    payload: typedPayload,
  };
}
```

### Usage

```ts
// Untyped payload
const e1 = parseEvent({ name: "user.login", timestamp: 1717000000000, payload: { id: 42 } });
// e1: Event<unknown>

// Typed payload via a validator
interface LoginPayload { userId: number }

const parseLogin: PayloadParser<LoginPayload> = (p) => {
  if (typeof p === "object" && p !== null && typeof (p as any).userId === "number") {
    return { userId: (p as any).userId };
  }
  throw new Error("expected { userId: number }");
};

const e2 = parseEvent(
  '{"name":"user.login","timestamp":"2024-05-29T12:00:00Z","payload":{"userId":42}}',
  parseLogin
);
// e2: Event<LoginPayload>, so e2.payload.userId is a number

// Error handling
try {
  parseEvent({ name: "", timestamp: "nope", payload: null });
} catch (err) {
  if (err instanceof EventParseError) console.error(err.path, err.message);
}
```

### Design notes

- **Runtime validation, not casting.** `raw as Event` would compile but prove nothing. Each field is checked, so the return type is trustworthy.
- **Flexible timestamps.** The parser accepts a `Date`, epoch milliseconds, or an ISO string, and always normalizes to a `Date`. Invalid dates are rejected.
- **Generic payload.** Without a validator, `payload` is `unknown`, so callers are forced to narrow it. With a validator, it's fully typed.
- **Errors include a path.** `EventParseError.path` tells you which field failed (`name`, `timestamp`, `payload`, or `$` for the root).
- **Name clash:** in browser or DOM-lib projects, `Event` shadows the global DOM `Event` type. If that's an issue, rename it to `AppEvent` or similar.
- If you already use a schema library like **Zod**, the equivalent is `z.object({ name: z.string().min(1), timestamp: z.coerce.date(), payload: z.unknown() })`. The `Event` type then comes from `z.infer`.

# Parsing an `Event` from Unknown Input

```typescript
/** The shape of a validated event. */
export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

/** Thrown when raw input cannot be parsed into an Event. */
export class EventParseError extends Error {
  constructor(message: string, public readonly field?: string) {
    super(field ? `Invalid "${field}": ${message}` : message);
    this.name = "EventParseError";
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function parseName(value: unknown): string {
  if (typeof value !== "string") {
    throw new EventParseError(`expected string, got ${typeof value}`, "name");
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new EventParseError("must not be empty", "name");
  }
  return trimmed;
}

function parseTimestamp(value: unknown): Date {
  let date: Date;

  if (value instanceof Date) {
    date = new Date(value.getTime());
  } else if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new EventParseError("must be a finite number", "timestamp");
    }
    date = new Date(value); // epoch milliseconds
  } else if (typeof value === "string") {
    if (value.trim() === "") {
      throw new EventParseError("must not be empty", "timestamp");
    }
    date = new Date(value); // ISO 8601 string
  } else {
    throw new EventParseError(
      `expected Date, number (epoch ms), or ISO string, got ${typeof value}`,
      "timestamp"
    );
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError(`could not parse ${JSON.stringify(value)}`, "timestamp");
  }
  return date;
}

function parsePayload(value: unknown): Record<string, unknown> {
  if (value === undefined) return {};
  if (!isPlainObject(value)) {
    throw new EventParseError("expected a plain object", "payload");
  }
  return { ...value };
}

/**
 * Validates unknown input and returns a typed Event.
 * Accepts either an object or a JSON string.
 * @throws {EventParseError} if the input is malformed.
 */
export function parseEvent(raw: unknown): Event {
  let input: unknown = raw;

  if (typeof raw === "string") {
    try {
      input = JSON.parse(raw);
    } catch {
      throw new EventParseError("input string is not valid JSON");
    }
  }

  if (!isPlainObject(input)) {
    throw new EventParseError("event must be a plain object");
  }

  return {
    name: parseName(input.name),
    timestamp: parseTimestamp(input.timestamp),
    payload: parsePayload(input.payload),
  };
}
```

## Usage

```typescript
