```typescript
type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";

interface RequestOptions {
  method: HttpMethod;
  url: string;
  headers?: Record<string, string>;
  body?: unknown;
}

function request({ method, url, headers = {}, body }: RequestOptions): Promise<Response> {
  const init: RequestInit = {
    method,
    headers: { ...headers },
  };

  if (body !== undefined && method !== "GET" && method !== "HEAD") {
    const isRawBody =
      typeof body === "string" ||
      body instanceof FormData ||
      body instanceof Blob ||
      body instanceof URLSearchParams ||
      body instanceof ArrayBuffer ||
      ArrayBuffer.isView(body) ||
      body instanceof ReadableStream;

    if (isRawBody) {
      init.body = body as BodyInit;
    } else {
      // Serialize plain objects/arrays as JSON
      init.body = JSON.stringify(body);
      const hasContentType = Object.keys(headers).some(
        (key) => key.toLowerCase() === "content-type"
      );
      if (!hasContentType) {
        (init.headers as Record<string, string>)["Content-Type"] = "application/json";
      }
    }
  }

  return fetch(url, init);
}
```

**Usage:**

```typescript
// GET
request({ method: "GET", url: "https://api.example.com/users" })
  .then((res) => res.json())
  .then(console.log);

// POST with JSON body (Content-Type set automatically)
request({
  method: "POST",
  url: "https://api.example.com/users",
  headers: { Authorization: "Bearer token123" },
  body: { name: "Alice", email: "alice@example.com" },
}).then((res) => {
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
});
```

**Notes:**
- `headers` and `body` are optional; `method` is restricted to valid HTTP verbs via a union type.
- Plain objects are JSON-serialized and get a `Content-Type: application/json` header unless you provide one yourself (checked case-insensitively).
- Native body types (`string`, `FormData`, `Blob`, etc.) are passed through untouched. For `FormData`, the browser sets the multipart boundary itself, so you should not set `Content-Type` manually.
- The body is ignored for `GET`/`HEAD`, since `fetch` throws if you send one with those methods.
- Like `fetch` itself, the Promise only rejects on network errors, not HTTP error statuses, so check `res.ok`.

```typescript
type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";

interface RequestOptions {
  method: HttpMethod;
  url: string;
  headers?: Record<string, string>;
  body?: unknown;
}

function request(options: RequestOptions): Promise<Response> {
  const { method, url, headers = {}, body } = options;

  const init: RequestInit = {
    method,
    headers: { ...headers },
  };

  if (body !== undefined && method !== "GET" && method !== "HEAD") {
    const isRawBody =
      typeof body === "string" ||
      body instanceof FormData ||
      body instanceof Blob ||
      body instanceof URLSearchParams ||
      body instanceof ArrayBuffer ||
      ArrayBuffer.isView(body) ||
      body instanceof ReadableStream;

    if (isRawBody) {
      init.body = body as BodyInit;
    } else {
      init.body = JSON.stringify(body);
      const hasContentType = Object.keys(headers).some(
        (key) => key.toLowerCase() === "content-type"
      );
      if (!hasContentType) {
        (init.headers as Record<string, string>)["Content-Type"] = "application/json";
      }
    }
  }

  return fetch(url, init);
}
```

**Usage:**

```typescript
// GET request
request({ method: "GET", url: "https://api.example.com/users" })
  .then((res) => res.json())
  .then((users) => console.log(users));

// POST with a JSON body (automatically serialized)
const res = await request({
  method: "POST",
  url: "https://api.example.com/users",
  headers: { Authorization: "Bearer token123" },
  body: { name: "Alice", email: "alice@example.com" },
});

if (!res.ok) {
  throw new Error(`Request failed: ${res.status} ${res.statusText}`);
}
```

**Notes:**

- **`method`** is a union of string literals, so typos like `"GTE"` are caught at compile time.
- **`headers`** and **`body`** are optional.
- **Plain objects and arrays** are automatically JSON-stringified, and `Content-Type: application/json` is set unless you've supplied your own (checked case-insensitively).
- **Native body types** (`string`, `FormData`, `Blob`, `URLSearchParams`, `ArrayBuffer`, typed arrays, streams) are passed through untouched. This lets the browser set the correct `Content-Type` itself, such as the multipart boundary for `FormData`.
- **The body is skipped for `GET`/`HEAD`**, since `fetch` throws a `TypeError` if you pass one.
