export type Event = {
  name: string;
  timestamp: number; // Unix timestamp in milliseconds
  payload: unknown;
};

export function parseEvent(raw: unknown): Event {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new TypeError("Event must be an object");
  }

  const { name, timestamp, payload } = raw as Record<string, unknown>;

  if (typeof name !== "string") {
    throw new TypeError("Event name must be a string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new TypeError("Event timestamp must be a finite number");
  }

  if (!Object.prototype.hasOwnProperty.call(raw, "payload")) {
    throw new TypeError("Event must include a payload");
  }

  return { name, timestamp, payload };
}
```

