export interface Event {
  name: string;
  timestamp: Date;
  payload: unknown;
}

export function parseEvent(raw: unknown): Event {
  if (typeof raw !== "object" || raw === null) {
    throw new TypeError("Event must be an object");
  }

  const value = raw as Record<string, unknown>;

  if (typeof value.name !== "string" || value.name.trim() === "") {
    throw new TypeError("Event name must be a non-empty string");
  }

  if (!Object.prototype.hasOwnProperty.call(value, "payload")) {
    throw new TypeError("Event payload is required");
  }

  const rawTimestamp = value.timestamp;
  if (
    typeof rawTimestamp !== "string" &&
    typeof rawTimestamp !== "number" &&
    !(rawTimestamp instanceof Date)
  ) {
    throw new TypeError("Event timestamp must be a string, number, or Date");
  }

  const timestamp =
    rawTimestamp instanceof Date
      ? new Date(rawTimestamp.getTime())
      : new Date(rawTimestamp);

  if (Number.isNaN(timestamp.getTime())) {
    throw new TypeError("Event timestamp is invalid");
  }

  return {
    name: value.name,
    timestamp,
    payload: value.payload,
  };
}
```

