# Event Parser in TypeScript

```typescript
// Event shape
interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

function parseEvent(raw: unknown): Event {
  if (typeof raw !== "object" || raw === null) {
    throw new Error("Event must be an object");
  }

  const { name, timestamp, payload } = raw as Record<string, unknown>;

  if (typeof name !== "string" || name.length === 0) {
    throw new Error("Event must have a non-empty 'name' string");
  }

  let parsedTimestamp: Date;
  if (typeof timestamp === "string" || typeof timestamp === "number") {
    parsedTimestamp = new Date(timestamp);
  } else {
    throw new Error("Event 'timestamp' must be a string or number");
  }
  if (isNaN(parsedTimestamp.getTime())) {
    throw new Error("Event 'timestamp' is not a valid date");
  }

  let parsedPayload: Record<string, unknown>;
  if (payload === undefined) {
    parsedPayload = {};
  } else if (typeof payload === "object" && payload !== null && !Array.isArray(payload)) {
    parsedPayload = payload as Record<string, unknown>;
  } else {
    throw new Error("Event 'payload' must be an object");
  }

  return { name, timestamp: parsedTimestamp, payload: parsedPayload };
}
```

## Usage

```typescript
const event = parseEvent({
  name: "user.created",
  timestamp: "2024-01-15T10:30:00Z",
  payload: { userId: 42, email: "a@b.com" },
});

console.log(event.name);      // "user.created"
console.log(event.timestamp); // 2024-01-15T10:30:00.000Z
console.log(event.payload);   // { userId: 42, email: "a@b.com" }
```

## Key points

- **Runtime validation**: Since `unknown` gives no compile-time guarantees, the function validates each field at runtime and throws descriptive errors.
- **Timestamp flexibility**: Accepts ISO strings or epoch numbers, normalized to a `Date`.
- **Optional payload**: Defaults to an empty object if omitted, but rejects non-object payloads (like arrays or primitives).
- **Type narrowing**: Uses `typeof` checks and `Record<string, unknown>` casts to safely extract fields.

