# Event Parser in TypeScript

```typescript
// Event shape
interface Event {
  name: string;
  timestamp: number;
  payload: Record<string, unknown>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new Error("Event must be an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new Error("Event 'name' must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new Error("Event 'timestamp' must be a finite number");
  }

  if (!isRecord(payload)) {
    throw new Error("Event 'payload' must be an object");
  }

  return { name, timestamp, payload };
}
```

## Usage

```typescript
const event = parseEvent({
  name: "user.signup",
  timestamp: Date.now(),
  payload: { userId: 42, plan: "pro" },
});
// ✅ { name: "user.signup", timestamp: ..., payload: {...} }

parseEvent("not an event");
// ❌ throws: Event must be an object

parseEvent({ name: "x", timestamp: "123", payload: {} });
// ❌ throws: Event 'timestamp' must be a finite number
```

## Notes

- **Type guards** (`isRecord`) let TypeScript narrow `unknown` safely instead of casting with `as`.
- **Runtime validation** is essential — `unknown` means the compiler knows nothing, so every field is checked before use.
- If you'd rather not throw, return a result type instead:

```typescript
