  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError("Event must be an object");
  }

  // Validate name
  if (typeof raw.name !== "string" || raw.name.length === 0) {
    throw new EventParseError("Event 'name' must be a non-empty string");
  }

  // Validate timestamp (accepts Date, ISO string, or epoch number)
  let timestamp: Date;
  if (raw.timestamp instanceof Date) {
    timestamp = raw.timestamp;
  } else if (typeof raw.timestamp === "string" || typeof raw.timestamp === "number") {
    timestamp = new Date(raw.timestamp);
  } else {
    throw new EventParseError("Event 'timestamp' must be a Date, string, or number");
  }

  if (Number.isNaN(timestamp.getTime())) {
    throw new EventParseError("Event 'timestamp' is not a valid date");
  }

  // Validate payload
  if (!isRecord(raw.payload)) {
    throw new EventParseError("Event 'payload' must be an object");
  }

  return {
    name: raw.name,
    timestamp,
    payload: raw.payload,
  };
}
```

