  timestamp: number;
  payload: unknown;
}

export function parseEvent(raw: unknown): Event {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new TypeError("Event must be a non-array object");
  }

  const record = raw as Record<string, unknown>;
  const { name, timestamp, payload } = record;

  if (typeof name !== "string") {
    throw new TypeError("Event.name must be a string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new TypeError("Event.timestamp must be a finite number");
  }

  return {
    name,
    timestamp,
    payload,
  };
}
```

If `payload` should have a stricter shape, replace `payload: unknown` with something like `payload: Record<string, unknown>` and validate it similarly.

# Parsing an `Event` from `unknown`

The key idea: `unknown` forces you to *prove* the shape before you can use it. Here's a small, dependency-free parser with a discriminated result so callers can't accidentally ignore failures.

```ts
// ---- 1. Declare the Event shape -------------------------------------------

export interface Event {
  name: string;
  timestamp: number; // epoch ms
  payload: Record<string, unknown>;
}

// A discriminated union so callers must handle the failure case.
export type ParseResult =
  | { ok: true; value: Event }
  | { ok: false; error: string };
```

```ts
// ---- 2. The parser --------------------------------------------------------

export function parseEvent(raw: unknown): ParseResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "event must be a non-null object" };
  }

  const obj = raw as Record<string, unknown>;

  const { name, timestamp, payload } = obj;

  if (typeof name !== "string" || name.length === 0) {
    return { ok: false, error: "`name` must be a non-empty string" };
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    return { ok: false, error: "`timestamp` must be a finite number" };
  }

  if (typeof payload !== "object" || payload === null || Array.isArray(payload)) {
    return { ok: false, error: "`payload` must be a plain object" };
  }

  return {
    ok: true,
    value: {
      name,
      timestamp,
      payload: payload as Record<string, unknown>,
    },
  };
}
```

## Usage

```ts
const result = parseEvent(JSON.parse(input));

if (!result.ok) {
  console.error("bad event:", result.error);
} else {
  const { name, timestamp, payload } = result.value; // fully typed
  console.log(name, new Date(timestamp), payload);
}
```

## Notes on the design

- **`unknown` over `any`** — the compiler refuses to let you touch `raw.name` until you've narrowed it. That's the whole point.
- **Discriminated result** — returning `Event | null` or throwing makes it easy to forget the failure path. `{ ok: true | false }` makes it a type error to skip.
- **`Number.isFinite`** — rejects `NaN` and `Infinity`, which `typeof x === "number"` alone would let through.
- **`Array.isArray` check on payload** — arrays are objects in JS; if you want to allow them, drop that clause.
- **`payload` is `Record<string, unknown>`** — you've validated it's an object, but not its contents. If you need deeper typing, either validate specific keys here or hand it to a schema library.

## If you'd rather throw

Some codebases prefer exceptions at the boundary. Same logic, different ergonomics:

```ts
export function parseEventOrThrow(raw: unknown): Event {
  const r = parseEvent(raw);
  if (!r.ok) throw new TypeError(`Invalid event: ${r.error}`);
  return r.value;
}
```

