export interface Event {
  name: string;
  timestamp: number; // epoch milliseconds
  payload: Record<string, unknown>;
}

// ---- 2. A small validation error type -------------------------------------

export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

// ---- 3. Type guards --------------------------------------------------------

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

// ---- 4. The parser ---------------------------------------------------------

export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("Event must be a non-null object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new EventParseError("`name` must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new EventParseError("`timestamp` must be a finite number");
  }

  if (!isPlainObject(payload)) {
    throw new EventParseError("`payload` must be a plain object");
  }

  return { name, timestamp, payload };
}
```

## Usage

```ts
const raw: unknown = JSON.parse('{"name":"click","timestamp":1712345678901,"payload":{"x":10}}');

const evt = parseEvent(raw);
// evt: Event
// evt.name      -> string
// evt.timestamp -> number
// evt.payload   -> Record<string, unknown>
```

## Notes on the design

- **`unknown` in, `Event` out.** The function is the trust boundary; everything downstream can rely on the type.
- **`isPlainObject`** rejects `null`, arrays, and non-objects in one shot — a common source of bugs when people write `typeof x === "object"` alone.
- **`Number.isFinite`** rejects `NaN` and `Infinity`, which `typeof === "number"` would happily accept.
- **`EventParseError`** lets callers distinguish parse failures from other errors (e.g. `catch (e) { if (e instanceof EventParseError) ... }`).
- **`payload` is `Record<string, unknown>`** — you know it's an object, but you don't know its fields yet. If you have a schema for payloads, validate it here too (or swap in Zod/Valibot for the whole thing).

## If you'd rather not throw

Return a discriminated union instead:

```ts
export type ParseResult =
  | { ok: true; event: Event }
  | { ok: false; error: string };

export function tryParseEvent(raw: unknown): ParseResult {
  try {
    return { ok: true, event: parseEvent(raw) };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Unknown error" };
  }
}
```

## With Zod (if you already use it)

```ts
import { z } from "zod";

const EventSchema = z.object({
  name: z.string().min(1),
  timestamp: z.number().finite(),
  payload: z.record(z.unknown()),
});

export type Event = z.infer<typeof EventSchema>;

export function parseEvent(raw: unknown): Event {
  return EventSchema.parse(raw); // throws ZodError on failure
}
```

Same contract, less hand-rolled code — pick whichever fits your project's dependency policy.

# Parsing `unknown` into a typed `Event`

The key idea: `unknown` forces you to narrow before use. We validate the shape at runtime and return a strongly-typed `Event`, throwing (or returning a result) on malformed input.

```ts
// ---- Event shape ----
export interface Event {
  name: string;
  timestamp: number; // epoch ms
  payload: Record<string, unknown>;
}

// ---- Type guard helpers ----
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// ---- Parser ----
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new TypeError("Event must be an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("Event.name must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new TypeError("Event.timestamp must be a finite number");
  }

  if (!isRecord(payload)) {
    throw new TypeError("Event.payload must be an object");
  }

  return { name, timestamp, payload };
}
```

## Usage

```ts
const e = parseEvent(JSON.parse('{"name":"click","timestamp":1700000000000,"payload":{"x":1}}'));
// e: Event
```

## Notes / variations

- **`unknown` vs `any`**: `unknown` is the right input type — it forces the checks above. If you accepted `any`, TypeScript would let you skip validation and you'd get runtime surprises.
- **Non-throwing variant**: if you prefer not to throw, return a discriminated union:

  ```ts
  type ParseResult =
    | { ok: true; event: Event }
    | { ok: false; error: string };

  export function tryParseEvent(raw: unknown): ParseResult {
    try {
      return { ok: true, event: parseEvent(raw) };
    } catch (err) {
      return { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
  }
  ```

- **Schema libraries**: for anything non-trivial, prefer `zod`, `valibot`, or `io-ts` — they generate the type *and* the validator from one source of truth:

  ```ts
  import { z } from "zod";

  export const EventSchema = z.object({
    name: z.string().min(1),
    timestamp: z.number().finite(),
    payload: z.record(z.unknown()),
  });

  export type Event = z.infer<typeof EventSchema>;
  export const parseEvent = (raw: unknown): Event => EventSchema.parse(raw);
  ```

- **Timestamp semantics**: I used epoch milliseconds. If your wire format uses ISO strings, change the check to `typeof timestamp === "string" && !Number.isNaN(Date.parse(timestamp))` and store the parsed number (or keep the string and rename the field to `timestampIso`).

```ts
export interface Event {
  name: string;
  timestamp: number;
  payload: unknown;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new TypeError("Event must be an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("Event.name must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new TypeError("Event.timestamp must be a finite number");
  }

  if (!("payload" in raw)) {
    throw new TypeError("Event.payload is required");
  }

  return {
    name,
    timestamp,
    payload,
