export interface Event {
  name: string;
  timestamp: number; // epoch milliseconds
  payload: Record<string, unknown>;
}

// ---- Type guard helpers ----
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// ---- Parser ----
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new TypeError("parseEvent: expected an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("parseEvent: 'name' must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new TypeError("parseEvent: 'timestamp' must be a finite number");
  }

  if (!isRecord(payload)) {
    throw new TypeError("parseEvent: 'payload' must be an object");
  }

  return { name, timestamp, payload };
}
```

## Usage

```ts
const raw: unknown = JSON.parse(
  '{"name":"user.created","timestamp":1700000000000,"payload":{"id":42}}'
);

const event = parseEvent(raw);
// event: Event
console.log(event.name);      // "user.created"
console.log(event.timestamp); // 1700000000000
console.log(event.payload);   // { id: 42 }
```

## Design notes

- **`unknown` in, `Event` out.** The function is the single trust boundary — callers don't need to cast.
- **Runtime validation is required.** TypeScript types are erased at compile time, so `raw as Event` would silently accept malformed data (e.g. `timestamp: "yesterday"`).
- **`Record<string, unknown>` for payload.** This keeps the payload open-ended but still object-shaped. If you know the payload schema, swap in a generic:

  ```ts
