    name: string;
    timestamp: number;
    payload: P;
  }

  export function parseEvent<P>(raw: unknown, parsePayload: (v: unknown) => P): Event<P> {
    // ...same checks, then:
    return { name, timestamp, payload: parsePayload(raw.payload) };
  }
  ```

- **Throwing vs. returning a result.** Throwing is idiomatic for a parser at a boundary. If you'd rather not throw, return a discriminated union:

  ```ts
