    throw new ParseError('expected a finite number', 'timestamp');
  }

  if (payload !== undefined && !isRecord(payload)) {
    throw new ParseError('expected an object', 'payload');
  }

  return {
    name,
    timestamp,
    payload: (payload as Record<string, unknown> | undefined) ?? {},
