# Parsing an Event from `unknown`

The key idea: `unknown` forces us to *prove* the shape at runtime before we can treat it as an `Event`. I'll define the type, then write a parser that validates each field and narrows safely.

```ts
// ---- 1. The Event shape ------------------------------------------------

export interface Event {
  name: string;
  timestamp: number;          // ms since epoch
  payload: Record<string, unknown>;
}

// A discriminated error so callers can react to *why* parsing failed.
export class EventParseError extends Error {
  constructor(message: string, readonly field?: string) {
    super(field ? `Invalid event: ${message} (field: ${field})` : `Invalid event: ${message}`);
    this.name = "EventParseError";
  }
}
```

```ts
// ---- 2. Small helpers to narrow `unknown` ------------------------------

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

function requireString(obj: Record<string, unknown>, key: string): string {
  const v = obj[key];
  if (typeof v !== "string" || v.length === 0) {
    throw new EventParseError(`expected non-empty string`, key);
  }
  return v;
}

function requireFiniteNumber(obj: Record<string, unknown>, key: string): number {
  const v = obj[key];
  if (typeof v !== "number" || !Number.isFinite(v)) {
    throw new EventParseError(`expected finite number`, key);
  }
  return v;
}

function requireObject(obj: Record<string, unknown>, key: string): Record<string, unknown> {
  const v = obj[key];
  if (!isPlainObject(v)) {
    throw new EventParseError(`expected plain object`, key);
  }
  return v;
}
```

```ts
// ---- 3. The parser -----------------------------------------------------

export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("expected an object");
  }

  // Optional convenience: accept a JSON string too.
  // (Remove if you want strictly object input.)
  // If you keep this, put it *before* the isPlainObject check.

  const name = requireString(raw, "name");
  const timestamp = requireFiniteNumber(raw, "timestamp");
  const payload = requireObject(raw, "payload");

  return { name, timestamp, payload };
}
```

## Usage

```ts
try {
  const evt = parseEvent(JSON.parse(input));
  console.log(evt.name, evt.timestamp, evt.payload);
} catch (err) {
  if (err instanceof EventParseError) {
    console.error(err.message); // e.g. "Invalid event: expected finite number (field: timestamp)"
  }
}
```

## Notes on the design

- **Why `unknown` and not `any`?** `any` would silently let you access `.name` without checking. `unknown` forces the narrowing helpers above — the compiler guarantees you never read a field you haven't validated.
- **Return type is `Event`, not `Event | null`.** Throwing on malformed input keeps the happy path clean and the failure path explicit. If you prefer a result type, swap to `{ ok: true; value: Event } | { ok: false; error: EventParseError }`.
- **`payload` as `Record<string, unknown>`** keeps it JSON-object-shaped without over-constraining it. If you know the payload is always a specific shape, make `Event` generic: `Event<T> = { name: string; timestamp: number; payload: T }` and add a schema validator for `T`.
- **Timestamp semantics.** I chose `number` (epoch ms). If you need a `Date`, convert at the boundary with `new Date(timestamp)` rather than storing a `Date` in the wire type — it keeps the type JSON-serializable.
- **Extending.** For real-world use, reach for [Zod](https://zod.dev) or [Valibot](https://valibot.dev) — they generate the runtime check *and* infer the `Event` type, so the two can't drift apart:

  ```ts
  const EventSchema = z.object({
    name: z.string().min(1),
    timestamp: z.number().finite(),
    payload: z.record(z.unknown()),
  });
  export type Event = z.infer<typeof EventSchema>;
  export const parseEvent = (raw: unknown): Event => EventSchema.parse(raw);
  ```

# Parsing an `Event` from `unknown`

The key idea: since `raw` is `unknown`, we can't trust its shape. We validate at runtime and narrow to a typed `Event`. I'll use a small hand-rolled validator (no dependencies) that throws on bad input.

```ts
export interface Event {
  name: string;
  timestamp: number;
  payload: Record<string, unknown>;
}

export class EventParseError extends Error {
  constructor(message: string, readonly raw: unknown) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseEvent(raw: unknown): Event {
  // Accept either a JSON string or an already-parsed object.
  let candidate: unknown = raw;
  if (typeof raw === "string") {
    try {
      candidate = JSON.parse(raw);
    } catch (err) {
      throw new EventParseError(
        `Event is not valid JSON: ${(err as Error).message}`,
        raw,
      );
    }
  }

  if (!isRecord(candidate)) {
    throw new EventParseError("Event must be an object", raw);
  }

  const { name, timestamp, payload } = candidate;

  if (typeof name !== "string" || name.length === 0) {
    throw new EventParseError("Event.name must be a non-empty string", raw);
  }

  // Timestamps: accept epoch millis as number, or ISO string.
  let ts: number;
  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    ts = timestamp;
  } else if (typeof timestamp === "string") {
    const parsed = Date.parse(timestamp);
    if (Number.isNaN(parsed)) {
      throw new EventParseError(
        "Event.timestamp string is not a valid date",
        raw,
      );
    }
    ts = parsed;
  } else {
    throw new EventParseError(
      "Event.timestamp must be a number or ISO date string",
      raw,
    );
  }

  // payload is optional; default to empty object.
  const resolvedPayload = payload === undefined ? {} : payload;
  if (!isRecord(resolvedPayload)) {
    throw new EventParseError("Event.payload must be an object", raw);
  }

  return { name, timestamp: ts, payload: resolvedPayload };
}
```

## Usage

```ts
const e = parseEvent('{"name":"signup","timestamp":1700000000000,"payload":{"userId":"u1"}}');
// e: Event -> { name: "signup", timestamp: 1700000000000, payload: { userId: "u1" } }

parseEvent({ name: "ping", timestamp: "2024-01-01T00:00:00Z" });
// -> { name: "ping", timestamp: 1704067200000, payload: {} }

parseEvent({ name: "", timestamp: 0 });
// throws EventParseError: Event.name must be a non-empty string
```

## Design notes

- **`unknown` in, `Event` out.** The function is the trust boundary — after it returns, downstream code can rely on the shape without further checks.
- **Narrowing via type guards.** `isRecord` is a user-defined type guard; combined with `typeof` checks, TypeScript narrows `candidate` to the exact fields we need.
- **Coercion, not just validation.** Timestamps are normalized to epoch millis so consumers don't have to handle both formats.
- **Fail loud.** Throwing a typed `EventParseError` (carrying the original `raw`) is usually preferable to returning `null`, because it preserves context. If you'd rather not throw, swap the throws for a `Result<Event, string>` return type — the validation logic is identical.
- **No `any`.** Every intermediate value stays `unknown` until it's been narrowed.

If you're already using **Zod** or **Valibot**, the idiomatic version is a one-liner schema plus `schema.parse(raw)` — but the hand-rolled version above keeps the dependency surface at zero and makes the coercion rules explicit.

```ts
export interface Event<T = unknown> {
  name: string;
  timestamp: number;
  payload: T;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseEvent<T = unknown>(raw: unknown): Event<T> {
  let value = raw;

  // Allow raw JSON strings as well as already-parsed objects.
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch {
      throw new Error("Invalid event: raw string is not valid JSON");
    }
  }

  if (!isRecord(value)) {
    throw new Error("Invalid event: expected an object");
  }

  const { name, timestamp, payload } = value;

  if (typeof name !== "string" || name.trim() === "") {
    throw new Error('Invalid event: "name" must be a non-empty string');
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new Error('Invalid event: "timestamp" must be a finite number');
  }

  if (!("payload" in value)) {
    throw new Error('Invalid event: "payload" is required');
  }

  return {
    name,
    timestamp,
    payload: payload as T,
  };
}
```

If you don’t need a generic payload, you can declare it as:

```ts
export interface Event {
  name: string;
  timestamp: number;
  payload: unknown;
}
```

```typescript
// Declared shape
interface Event {
  name: string;
  timestamp: number; // epoch milliseconds
  payload: Record<string, unknown>;
}

// Type guard helpers
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError("Event must be a plain object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new EventParseError("Event.name must be a non-empty string");
  }

  if (typeof timestamp !== "number" || !Number.isFinite(timestamp)) {
    throw new EventParseError("Event.timestamp must be a finite number");
  }

  // payload is optional; default to an empty object
  let normalizedPayload: Record<string, unknown>;
  if (payload === undefined || payload === null) {
    normalizedPayload = {};
  } else if (isPlainObject(payload)) {
    normalizedPayload = payload;
  } else {
    throw new EventParseError("Event.payload must be a plain object");
  }

  return {
    name,
    timestamp,
    payload: normalizedPayload,
  };
}
```

Key points:

- **`Event` interface** declares the shape: `name: string`, `timestamp: number` (epoch ms), `payload: Record<string, unknown>`.
- **`parseEvent` accepts `unknown`** and narrows it step by step, so callers can pass anything (e.g. `JSON.parse` output) without unsafe casts.
- **Validation** rejects non-objects, empty/invalid `name`, non-finite `timestamp`, and non-object `payload`. `payload` is optional and defaults to `{}`.
- **`EventParseError`** gives callers a specific error type to catch.

If you prefer a non-throwing variant, you can wrap it:

