export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EventParseError';
  }
}

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new EventParseError('Event must be an object');
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== 'string' || name.length === 0) {
    throw new EventParseError('Event.name must be a non-empty string');
  }

  let ts: number;
  if (typeof timestamp === 'number' && Number.isFinite(timestamp)) {
    ts = timestamp;
  } else if (typeof timestamp === 'string') {
    const parsed = Date.parse(timestamp);
    if (Number.isNaN(parsed)) {
      throw new EventParseError('Event.timestamp string is not a valid date');
    }
    ts = parsed;
  } else {
    throw new EventParseError(
      'Event.timestamp must be a finite number or ISO date string',
    );
  }

  if (payload !== undefined && !isPlainObject(payload)) {
    throw new EventParseError('Event.payload must be a plain object');
  }

  return {
    name,
    timestamp: ts,
    payload: (payload as Record<string, unknown>) ?? {},
  };
}
```

Notes:
- `Event` is declared as an interface with `name`, `timestamp` (ms since epoch), and `payload`.
- `parseEvent` accepts `unknown` and narrows it with runtime checks.
- Timestamps accept either a finite number or a parseable date string (converted to ms).
- `payload` defaults to `{}` if omitted, but must be a plain object if present.
- A dedicated `EventParseError` makes failures easy to distinguish from other exceptions.

```typescript
// Event shape
export interface Event {
  name: string;
  timestamp: number;
  payload: unknown;
}

// Custom error so callers can distinguish parse failures
export class EventParseError extends Error {
  constructor(message: string, readonly cause?: unknown) {
    super(message);
    this.name = 'EventParseError';
  }
}

// Type guard helpers
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Parse an unknown value into a typed Event.
 * Throws EventParseError if the shape is invalid.
 */
export function parseEvent(raw: unknown): Event {
  // Accept either an already-parsed object, or a JSON string.
  let candidate: unknown = raw;
  if (typeof raw === 'string') {
    try {
      candidate = JSON.parse(raw);
    } catch (err) {
      throw new EventParseError('Event is not valid JSON', err);
    }
  }

  if (!isRecord(candidate)) {
    throw new EventParseError('Event must be an object');
  }

  const { name, timestamp, payload } = candidate;

  if (typeof name !== 'string' || name.length === 0) {
    throw new EventParseError('Event.name must be a non-empty string');
  }

  if (typeof timestamp !== 'number' || !Number.isFinite(timestamp)) {
    throw new EventParseError('Event.timestamp must be a finite number');
  }

  // payload may be anything, including undefined. We keep it as-is.
  return {
    name,
    timestamp,
    payload: payload ?? null,
  };
}
```

Notes on design choices:

- **`payload: unknown`** keeps the type honest — the parser can't know what payload shape belongs to which event name. If you want stronger typing, make `Event` generic (`Event<T = unknown>`) and cast at call sites where you trust the producer.
- **Accepts string or object**: many event sources hand you JSON strings (from a socket, queue, or `localStorage`). Parsing both keeps the call site simple.
- **Rejects arrays and `null`** via `isRecord`, since `typeof null === 'object'` is a classic trap.
- **`Number.isFinite`** rejects `NaN` and `Infinity`, which are valid `number` values but almost never valid timestamps.
- **`EventParseError`** lets callers `catch` and distinguish a schema failure from an unrelated bug.

# Typed Event Parser

```ts
// ---------- Types ----------

export interface Event {
  name: string;
  timestamp: number;
  payload: Record<string, unknown>;
}

// Optional: a discriminated error for callers who want to handle failures
export class EventParseError extends Error {
  constructor(message: string, readonly raw: unknown) {
    super(message);
    this.name = 'EventParseError';
  }
}

// ---------- Parser ----------

export function parseEvent(raw: unknown): Event {
  if (typeof raw !== 'object' || raw === null) {
    throw new EventParseError('Event must be a non-null object', raw);
  }

  const obj = raw as Record<string, unknown>;

  const { name, timestamp, payload } = obj;

  if (typeof name !== 'string' || name.length === 0) {
    throw new EventParseError('Event.name must be a non-empty string', raw);
  }

  if (typeof timestamp !== 'number' || !Number.isFinite(timestamp)) {
    throw new EventParseError('Event.timestamp must be a finite number', raw);
  }

  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
    throw new EventParseError('Event.payload must be a plain object', raw);
  }

  return {
    name,
    timestamp,
    payload: payload as Record<string, unknown>,
  };
}
```

## Usage

```ts
try {
  const evt = parseEvent(JSON.parse(input));
  console.log(evt.name, evt.timestamp);
} catch (err) {
  if (err instanceof EventParseError) {
    console.error('Bad event:', err.message, err.raw);
  } else {
    throw err;
  }
}
```

## Design notes

- **`unknown` in, `Event` out.** The input is validated before any property access, so the function is safe even under `strict` TS.
- **Explicit checks, no `as` shortcuts on the input.** The only cast is on `payload` after we've confirmed it's a non-null, non-array object.
- **Rejects arrays for `payload`.** Arrays are objects in JS; a plain `typeof === 'object'` check would let them through. If you actually want to allow arrays, drop the `Array.isArray` clause.
- **Rejects `NaN` / `Infinity` timestamps.** `Number.isFinite` is stricter than `typeof === 'number'`.
- **Custom error class** so callers can distinguish parse failures from unrelated exceptions. Swap for `return null` or a `Result<Event>` type if you prefer non-throwing APIs.

### Variant: throwing vs. returning a result

If you'd rather not throw, replace the throws with a discriminated union:

```ts
type ParseResult =
  | { ok: true; event: Event }
  | { ok: false; error: string };

export function tryParseEvent(raw: unknown): ParseResult {
  try {
    return { ok: true, event: parseEvent(raw) };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : 'Unknown error' };
  }
}
```

For production, consider swapping the hand-written checks for **Zod** or **Valibot** — you get the same runtime safety with less boilerplate and automatic type inference:

```ts
import { z } from 'zod';

const EventSchema = z.object({
  name: z.string().min(1),
  timestamp: z.number().finite(),
  payload: z.record(z.unknown()),
});

export type Event = z.infer<typeof EventSchema>;

export function parseEvent(raw: unknown): Event {
  return EventSchema.parse(raw);
}
```

```ts
// The typed shape we promise to return.
export interface Event {
  name: string;
  timestamp: number; // epoch milliseconds
  payload: Record<string, unknown>;
}

// Custom error so callers can distinguish parse failures.
export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EventParseError';
  }
}

// Narrowing helpers — keep them small and composable.
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

/**
 * Parse an unknown value into a strongly-typed Event.
 * Throws EventParseError if the input doesn't match the expected shape.
 */
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError('Event must be an object');
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== 'string' || name.length === 0) {
    throw new EventParseError('Event.name must be a non-empty string');
  }

  if (!isFiniteNumber(timestamp)) {
    throw new EventParseError('Event.timestamp must be a finite number');
  }

  if (!isRecord(payload)) {
    throw new EventParseError('Event.payload must be an object');
  }

  return {
    name,
    timestamp,
    payload,
  };
}
```

A few notes on the design choices:

- **`unknown` in, `Event` out.** The input is treated as untrusted; every field is validated before being copied into the result. No `as` casts on the way in.
- **`isRecord` excludes arrays and `null`.** Both are `typeof 'object'` in JS, so they need explicit rejection.
- **`Number.isFinite`** rejects `NaN`, `Infinity`, and non-numbers in one check — useful because `typeof NaN === 'number'`.
- **Non-empty `name`** is enforced; drop that check if empty strings are legal in your domain.
- **Payload is returned as-is** (a shallow reference). If you need to guarantee the caller can't mutate the original, clone it: `payload: { ...payload }`. For deep immutability you'd want a structured clone or a schema library.
- **Throwing vs. returning a Result.** If you'd rather not throw, change the signature to `parseEvent(raw: unknown): { ok: true; value: Event } | { ok: false; error: string }` — the validation logic stays identical.

If this is fed by an untrusted boundary (HTTP, queue, `JSON.parse`), consider swapping the hand-rolled guards for a schema library like Zod or Valibot so the shape and validator stay in sync as the Event evolves.

# Parsing `unknown` into a Typed `Event`

The key idea: `unknown` forces you to narrow before use. Below is a small, dependency-free parser using a type guard.

```ts
// ---- 1. Declare the Event shape ----

export interface Event {
  name: string;
  timestamp: Date;
  payload: Record<string, unknown>;
}

// ---- 2. Type guard for the raw shape ----

function isRawEvent(value: unknown): value is {
  name: string;
  timestamp: string | number | Date;
  payload?: unknown;
} {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  if (typeof v.name !== "string") return false;
  const t = v.timestamp;
  if (
    typeof t !== "string" &&
    typeof t !== "number" &&
    !(t instanceof Date)
  ) {
    return false;
  }
  return true;
}

// ---- 3. The parser ----

export function parseEvent(raw: unknown): Event {
  if (!isRawEvent(raw)) {
    throw new TypeError("Invalid event: expected { name, timestamp, payload? }");
  }

  const { name, timestamp, payload } = raw as {
    name: string;
    timestamp: string | number | Date;
    payload?: unknown;
  };

  const ts =
    timestamp instanceof Date ? timestamp : new Date(timestamp);

  if (Number.isNaN(ts.getTime())) {
    throw new TypeError(`Invalid event timestamp: ${String(timestamp)}`);
  }

  const normalizedPayload: Record<string, unknown> =
    typeof payload === "object" && payload !== null && !Array.isArray(payload)
      ? (payload as Record<string, unknown>)
      : payload === undefined
        ? {}
        : { value: payload };

  return {
    name,
    timestamp: ts,
    payload: normalizedPayload,
  };
}
```

## Usage

```ts
const e = parseEvent({
  name: "user.signup",
  timestamp: "2024-01-15T10:00:00Z",
  payload: { userId: 42 },
});

e.name;            // string
e.timestamp;       // Date
e.payload.userId;  // unknown
```

## Design notes

- **`unknown`, not `any`** — the caller is forced to go through the guard before accessing fields.
- **`timestamp` accepts `string | number | Date`** — JSON sources give strings/numbers, in-process callers may pass `Date`. Normalized to `Date` on output.
- **`payload` defaults to `{}`** — makes downstream code simpler; scalars get wrapped as `{ value }` so the return type stays `Record<string, unknown>`.
- **Throws `TypeError`** — swap for a `Result<Event, ParseError>` type if you prefer not to throw across boundaries (e.g. in a message handler).

If you want a schema-driven version, the same function becomes a one-liner with **Zod**:

```ts
import { z } from "zod";

const EventSchema = z.object({
  name: z.string(),
  timestamp: z.coerce.date(),
  payload: z.record(z.unknown()).default({}),
});

export type Event = z.infer<typeof EventSchema>;

export function parseEvent(raw: unknown): Event {
  return EventSchema.parse(raw);
}
```

# Parsing an Unknown into a Typed `Event`

Here's a robust implementation with runtime validation. The key idea: TypeScript's types are erased at runtime, so we need explicit checks to safely narrow `unknown` into our `Event` shape.

```typescript
// ---- Domain type ----
export interface Event {
  name: string;
  timestamp: number; // Unix ms
  payload: Record<string, unknown>;
}

// ---- Type guard helpers ----
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isEvent(value: unknown): value is Event {
  if (!isRecord(value)) return false;
  return (
    typeof value.name === "string" &&
    typeof value.timestamp === "number" &&
    Number.isFinite(value.timestamp) &&
    isRecord(value.payload)
  );
}

// ---- Parser ----
export function parseEvent(raw: unknown): Event {
  // If it's a JSON string, try to decode first.
  let candidate: unknown = raw;
  if (typeof raw === "string") {
    try {
      candidate = JSON.parse(raw);
    } catch {
      throw new TypeError("parseEvent: input string is not valid JSON");
    }
  }

  if (!isEvent(candidate)) {
    throw new TypeError(
      "parseEvent: expected { name: string, timestamp: number, payload: object }"
    );
  }

  // Return a fresh object so callers can't mutate the original reference.
  return {
    name: candidate.name,
    timestamp: candidate.timestamp,
    payload: { ...candidate.payload },
  };
}
```

## Usage

```ts
const e = parseEvent('{"name":"click","timestamp":1700000000000,"payload":{"x":10,"y":20}}');
// e: Event

parseEvent({ name: "click", timestamp: Date.now(), payload: {} }); // ok
parseEvent({ name: 42 }); // throws TypeError
parseEvent("not json");   // throws TypeError
```

## Design notes

- **`unknown`, not `any`** — forces you to prove the shape before using it.
- **Type guard (`isEvent`)** — reusable, and TypeScript narrows the type inside the `if`.
- **`Number.isFinite`** — rejects `NaN` and `Infinity`, which `typeof x === "number"` would let through.
- **`!Array.isArray`** — arrays are objects, but they're not a valid `payload` record.
- **Copy on return** — avoids aliasing the caller's object.

If you'd prefer a non-throwing API, swap the throw for a result type:

```ts
export type ParseResult =
  | { ok: true; value: Event }
  | { ok: false; error: string };
```

Or, if you're already using a schema library, this whole thing collapses to:

```ts
import { z } from "zod";
const EventSchema = z.object({
  name: z.string(),
  timestamp: z.number().finite(),
  payload: z.record(z.unknown()),
});
export type Event = z.infer<typeof EventSchema>;
export const parseEvent = (raw: unknown): Event => EventSchema.parse(raw);
```

# TypeScript Fetch Wrapper

```typescript
type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS';

interface RequestOptions {
  method: HttpMethod;
  url: string;
  headers?: Record<string, string>;
  body?: unknown;
}

async function request<T = unknown>(options: RequestOptions): Promise<T> {
  const { method, url, headers = {}, body } = options;

  const init: RequestInit = {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
  };

  // Only attach a body for methods that allow one.
  if (body !== undefined && method !== 'GET' && method !== 'HEAD') {
    init.body = typeof body === 'string' ? body : JSON.stringify(body);
  }

  const response = await fetch(url, init);

  if (!response.ok) {
    throw new Error(`HTTP ${response.status} ${response.statusText} for ${method} ${url}`);
  }

  // Handle empty responses (e.g. 204 No Content)
  const contentType = response.headers.get('content-type') ?? '';
  if (response.status === 204 || !contentType.includes('application/json')) {
    return (await response.text()) as unknown as T;
  }

  return (await response.json()) as T;
}
```

### Usage

```typescript
interface User {
  id: number;
  name: string;
}

// GET
const user = await request<User>({
  method: 'GET',
  url: 'https://api.example.com/users/1',
  headers: { Authorization: 'Bearer token' },
});

// POST
const created = await request<User>({
  method: 'POST',
  url: 'https://api.example.com/users',
  body: { name: 'Alice' },
});
```

### Notes on the design

- **`body?: unknown`** — accepts any serializable value; the function serializes it with `JSON.stringify` unless it's already a string. This keeps callers from having to stringify manually.
- **Guarding GET/HEAD** — the Fetch spec throws if you pass a body with `GET` or `HEAD`, so we skip attaching one.
- **`T = unknown` generic** — lets callers type the parsed response. Defaults to `unknown` so you don't accidentally treat the response as `any`.
- **Error handling** — non-2xx responses throw with the status, method, and URL for easier debugging. In a real app you might want to parse the error body too.
- **Non-JSON responses** — falls back to `response.text()` so plain-text endpoints don't blow up on `.json()`.

If you need streaming, cancellation, or retries, wrap this in an `AbortController`/retry layer rather than complicating `RequestOptions`.

```typescript
interface RequestOptions {
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS';
  url: string;
  headers?: Record<string, string>;
  body?: BodyInit | null;
}

function request(options: RequestOptions): Promise<Response> {
  const { method, url, headers, body } = options;

  return fetch(url, {
    method,
    headers,
    body,
  });
}
```

A few notes on the design choices:

- **`method`** is a string-literal union so you get autocomplete and compile-time safety against typos like `'GETT'`. If you want to allow arbitrary methods, change it to `string`.
- **`headers`** is optional and typed as `Record<string, string>`, which maps cleanly onto the `HeadersInit` that `fetch` accepts.
- **`body`** uses the DOM's `BodyInit` type (covers `string`, `Blob`, `FormData`, `URLSearchParams`, `ArrayBuffer`, etc.). It's optional so `GET`/`HEAD` requests don't need it.
- The function returns `Promise<Response>` — the native `fetch` return type. If you want to parse JSON automatically, you could wrap it:

```typescript
async function requestJson<T>(options: RequestOptions): Promise<T> {
  const res = await request(options);
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  }
  return res.json() as Promise<T>;
}
```

If you're targeting Node without DOM libs, replace `BodyInit` with `string | Buffer | Uint8Array | ...` and `Response` with the appropriate type from `undici` or `node-fetch`.

