```ts
/** Arbitrary JSON-ish payload attached to an event. */
export interface EventPayload {
  [key: string]: unknown;
}

export interface Event {
  /** Dotted event name, e.g. "user.created". */
  name: string;
  /** Unix epoch milliseconds. */
  timestamp: number;
  payload: EventPayload;
}
```

## The parser

```ts
export class ParseError extends Error {
  constructor(message: string, readonly path: string) {
    super(`${message} (at ${path})`);
    this.name = "ParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Accepts epoch millis (number) or an ISO-8601 string. */
function toTimestamp(value: unknown, path: string): number {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new ParseError(`timestamp must be a finite number, got ${value}`, path);
    }
    return value;
  }
  if (typeof value === "string") {
    const ms = Date.parse(value);
    if (Number.isNaN(ms)) {
      throw new ParseError(`timestamp is not a valid date string: ${value}`, path);
    }
    return ms;
  }
  throw new ParseError(`timestamp must be a number or string, got ${typeof value}`, path);
}

export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new ParseError(`event must be an object, got ${typeof raw}`, "$");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new ParseError(`name must be a non-empty string, got ${typeof name}`, "$.name");
  }

  if (!("timestamp" in raw)) {
    throw new ParseError("timestamp is required", "$.timestamp");
  }

  if (!("payload" in raw)) {
    throw new ParseError("payload is required", "$.payload");
  }

  if (!isRecord(payload)) {
    throw new ParseError(`payload must be an object, got ${typeof payload}`, "$.payload");
  }

  return {
    name: name.trim(),
    timestamp: toTimestamp(timestamp, "$.timestamp"),
    payload,
  };
}
```

## Notes

- **`raw: unknown` forces a runtime check** — the compiler won't let you read `.name` off an unvalidated value, so every field is narrowed before use.
- **The `in` checks distinguish "missing" from "present but wrong type"**, which gives better error messages than a single `typeof` guard.
- **`payload` is kept as `Record<string, unknown>`** rather than `any`, so consumers still get type safety on the inside of the payload while the outer shape is fixed.
- If you want a *typed* payload per event name, the usual pattern is a generic:

```ts
export function parseEvent<P extends EventPayload = EventPayload>(raw: unknown): Event & { payload: P } {
  return parseEvent(raw) as Event & { payload: P };
}
```

…paired with a per-event schema (zod, valibot, etc.) so `P` is actually validated rather than merely asserted.

