## Parser

```ts
export class EventParseError extends Error {
  constructor(message: string, readonly raw: unknown) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

/** Accepts epoch ms (number) or an ISO-8601 string; returns epoch ms. */
function toEpochMs(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (isNonEmptyString(value)) {
    const ms = Date.parse(value);
    return Number.isNaN(ms) ? undefined : ms;
  }
  return undefined;
}

export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError("Event must be an object", raw);
  }

  const { name, timestamp, payload } = raw;

  if (!isNonEmptyString(name)) {
    throw new EventParseError("Event.name must be a non-empty string", raw);
  }

  const ts = toEpochMs(timestamp);
  if (ts === undefined) {
    throw new EventParseError(
      "Event.timestamp must be epoch milliseconds or an ISO-8601 string",
      raw,
    );
  }

  if (payload !== undefined && !isRecord(payload)) {
    throw new EventParseError("Event.payload must be an object", raw);
  }

  return {
    name: name.trim(),
    timestamp: ts,
    payload: (payload as EventPayload | undefined) ?? {},
  };
}
```

## Notes

- `raw: unknown` forces callers to pass untrusted data; the parser narrows it via type guards rather than casts.
- `payload` is typed as `Record<string, unknown>` so consumers must narrow values before use — you can swap in a discriminated union of payload types if you want stronger guarantees.
- If you'd rather not throw, return a result type instead:

```ts
