export function tryParseEvent(raw: unknown): ParseResult<Event> {
  try {
    return { ok: true, value: parseEvent(raw) };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Unknown error" };
  }
}
```

