  | { ok: true; value: T }
  | { ok: false; error: EventParseError };

export function safeParseEvent(raw: unknown): ParseResult<Event> {
  try {
    return { ok: true, value: parseEvent(raw) };
  } catch (error) {
    return {
      ok: false,
      error:
        error instanceof EventParseError
          ? error
          : new EventParseError(String(error), "$"),
    };
  }
}
```

