```ts
export class ParseError extends Error {
  constructor(message: string, readonly path: string) {
    super(`${message} (at ${path})`);
    this.name = "ParseError";
  }
}

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

function parseTimestamp(value: unknown, path: string): number {
  if (typeof value === "number" && Number.isFinite(value)) {
    // Heuristic: values that look like seconds are widened to ms.
    return value < 1e12 ? Math.round(value * 1000) : Math.round(value);
  }
  if (value instanceof Date) {
    const ms = value.getTime();
    if (Number.isNaN(ms)) throw new ParseError("Invalid Date", path);
    return ms;
  }
  if (typeof value === "string") {
    const ms = Date.parse(value);
    if (Number.isNaN(ms)) throw new ParseError(`Unparseable timestamp: ${value}`, path);
    return ms;
  }
  throw new ParseError(`Expected timestamp, got ${typeof value}`, path);
}

export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new ParseError(`Expected an object, got ${raw === null ? "null" : typeof raw}`, "$");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new ParseError("Expected a non-empty string name", "$.name");
  }

  if (timestamp === undefined) {
    throw new ParseError("Missing timestamp", "$.timestamp");
  }

  if (payload !== undefined && !isPlainObject(payload)) {
    throw new ParseError("Expected payload to be an object", "$.payload");
  }

  return {
    name: name.trim(),
    timestamp: parseTimestamp(timestamp, "$.timestamp"),
    payload: (payload ?? {}) as EventPayload,
  };
}
```

## Notes

- **`unknown` in, `Event` out** — the input is untrusted, so the function validates at runtime rather than casting. A cast (`raw as Event`) would only move the error to the first property access.
- **Timestamps are normalized to epoch ms** so downstream code compares one unit. The `< 1e12` heuristic distinguishes seconds from milliseconds; if your inputs are always ms, drop it.
- **Errors carry a path** (`$.payload`) so failures are debuggable in nested pipelines.
- **Optional fields**: `payload` defaults to `{}` and `timestamp` is required. If you'd rather have a `Partial`/discriminated union for event kinds, the same pattern extends — add a `kind` field and narrow on it.

