  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Validates and narrows an unknown value into an Event.
 * Throws TypeError if the shape is invalid.
 */
export function parseEvent(raw: unknown): Event {
  if (!isPlainObject(raw)) {
    throw new TypeError("parseEvent: expected an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new TypeError("parseEvent: 'name' must be a non-empty string");
  }

  let ts: number;
  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    ts = timestamp;
  } else if (typeof timestamp === "string") {
    const parsed = Date.parse(timestamp);
    if (Number.isNaN(parsed)) {
      throw new TypeError("parseEvent: 'timestamp' must be a valid date");
    }
    ts = parsed;
  } else {
    throw new TypeError("parseEvent: 'timestamp' must be a number or date string");
  }

  if (!isPlainObject(payload)) {
    throw new TypeError("parseEvent: 'payload' must be an object");
  }

  // Unknown extra fields on `raw` are intentionally dropped.
  return { name, timestamp: ts, payload };
}
```

