## The parser

```ts
export class EventParseError extends TypeError {
  constructor(
    message: string,
    readonly field: string,
    readonly value: unknown,
  ) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Normalizes a timestamp to epoch ms. Accepts a number or an ISO-8601 string. */
function toEpochMillis(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "string") {
    const parsed = Date.parse(value);
    return Number.isNaN(parsed) ? undefined : parsed;
  }
  return undefined;
}

export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError("Event must be a non-null object", "<root>", raw);
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("Event.name must be a non-empty string", "name", name);
  }

  const millis = toEpochMillis(timestamp);
  if (millis === undefined) {
    throw new EventParseError(
      "Event.timestamp must be a finite number (epoch ms) or a parseable date string",
      "timestamp",
      timestamp,
    );
  }

  if (!isRecord(payload)) {
    throw new EventParseError("Event.payload must be a non-null object", "payload", payload);
  }

  return { name, timestamp: millis, payload };
}
```

