## The parser

Because the input is `unknown`, TypeScript can't help you — the value has to be checked at runtime before it can be narrowed to `Event`.

```ts
export class EventParseError extends Error {
  readonly issues: string[];

  constructor(issues: string[]) {
    super(`Invalid event: ${issues.join("; ")}`);
    this.name = "EventParseError";
    this.issues = issues;
  }
}

export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError([`expected an object, received ${describe(raw)}`]);
  }

  const issues: string[] = [];

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    issues.push("`name` must be a non-empty string");
  }

  const ts = parseTimestamp(timestamp);
  if (ts === undefined) {
    issues.push("`timestamp` must be a finite number (epoch ms) or a parseable date string");
  }

  if (!isRecord(payload)) {
    issues.push("`payload` must be an object");
  }

  if (issues.length > 0) {
    throw new EventParseError(issues);
  }

  // Narrowed by the checks above.
  return { name: name as string, timestamp: ts as number, payload: payload as EventPayload };
}

// --- helpers ---------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTimestamp(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "string") {
    const parsed = Date.parse(value);
    return Number.isNaN(parsed) ? undefined : parsed;
  }
  return undefined;
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}
