### The parser

```ts
const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/**
 * Accepts a timestamp as epoch millis (number) or an ISO-8601 string.
 * Returns epoch millis, or throws.
 */
function toEpochMillis(value: unknown, field: string): number {
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new EventParseError(`timestamp must be a finite number`, field);
    }
    return value;
  }
  if (typeof value === "string") {
    const ms = Date.parse(value);
    if (Number.isNaN(ms)) {
      throw new EventParseError(`timestamp is not a valid date: ${value}`, field);
    }
    return ms;
  }
  throw new EventParseError(`timestamp must be a number or ISO string`, field);
}

/**
 * Parses untrusted input into an `Event`.
 *
 * @throws {EventParseError} if the input does not conform to the Event shape.
 */
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError("event must be an object", "<root>");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("name must be a non-empty string", "name");
  }

  if (!("timestamp" in raw)) {
    throw new EventParseError("timestamp is required", "timestamp");
  }

  if (!("payload" in raw)) {
    throw new EventParseError("payload is required", "payload");
  }
  if (!isRecord(payload)) {
    throw new EventParseError("payload must be an object", "payload");
  }

  return {
    name: name.trim(),
    timestamp: toEpochMillis(timestamp, "timestamp"),
    payload,
  };
}
```

