```ts
/** A validated event. `timestamp` is always normalized to an ISO 8601 string. */
export interface Event {
  readonly name: string;
  readonly timestamp: string;
  readonly payload: Readonly<Record<string, unknown>>;
}

export class EventParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventParseError";
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Narrows `unknown` input to a valid `Event`.
 * Throws `EventParseError` if the shape or field types are invalid.
 */
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new EventParseError("Event must be an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.trim() === "") {
    throw new EventParseError("Event.name must be a non-empty string");
  }

  let date: Date;
  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    date = new Date(timestamp); // epoch milliseconds
  } else if (typeof timestamp === "string") {
    date = new Date(timestamp); // ISO 8601 / parseable date string
  } else {
    throw new EventParseError("Event.timestamp must be a string or a number");
  }

  if (Number.isNaN(date.getTime())) {
    throw new EventParseError("Event.timestamp must be a valid date");
  }

  if (!isRecord(payload)) {
    throw new EventParseError("Event.payload must be an object");
  }

  return {
    name: name.trim(),
    timestamp: date.toISOString(),
    payload,
  };
}
```

Notes:

- `raw: unknown` is treated as untrusted: every field is checked at runtime before the value is returned as `Event`.
- `timestamp` accepts either an ISO string or epoch milliseconds and is normalized to ISO 8601, so downstream code has one format to handle.
- If you know the payload shape, make the function generic and validate it too, e.g. `parseEvent<T extends Record<string, unknown>>(raw: unknown): Event<T>` with a schema check on `payload`.

Example:

```ts
const e = parseEvent(JSON.parse(json));
console.log(e.name, e.timestamp, e.payload);
```

