/** The payload carried by an event: an arbitrary bag of data. */
export interface EventPayload {
  [key: string]: unknown;
}

/** The shape returned by `parseEvent`. */
export interface Event {
  name: string;
  /** Unix epoch milliseconds. */
  timestamp: number;
  payload: EventPayload;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Parses an untrusted value into an `Event`.
 * Throws a `TypeError` if the value does not match the expected shape.
 */
export function parseEvent(raw: unknown): Event {
  if (!isRecord(raw)) {
    throw new TypeError("Event must be an object");
  }

  const { name, timestamp, payload } = raw;

  if (typeof name !== "string" || name.length === 0) {
    throw new TypeError("Event.name must be a non-empty string");
  }

  let parsedTimestamp: number;
  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    parsedTimestamp = timestamp;
  } else if (typeof timestamp === "string") {
    const asDate = Date.parse(timestamp);
    if (Number.isNaN(asDate)) {
      throw new TypeError("Event.timestamp must be a valid date");
    }
    parsedTimestamp = asDate;
  } else {
    throw new TypeError("Event.timestamp must be a number or an ISO date string");
  }

  if (!isRecord(payload)) {
    throw new TypeError("Event.payload must be an object");
  }

  return {
    name,
    timestamp: parsedTimestamp,
    payload: payload as EventPayload,
  };
}
```

Notes:

- `raw: unknown` forces callers to treat the input as untrusted, so the function validates at runtime rather than relying on the type system.
- The `isRecord` helper is a type guard, so TypeScript narrows `raw` to `Record<string, unknown>` and the destructured fields become `unknown`.
- Timestamps are normalized to epoch milliseconds; ISO date strings are accepted and converted.
- `payload` keeps its values typed as `unknown` so downstream code must narrow them before use.

