## The function

```ts
export async function request(options: RequestOptions): Promise<Response> {
  const {
    method = 'GET',
    url,
    headers = {},
    body = null,
  } = options;

  // GET/HEAD requests must not carry a body.
  const finalBody = method === 'GET' || method === 'HEAD' ? null : body;

  return fetch(url, {
    method,
    headers,
    body: finalBody,
  });
}
```

## Usage

```ts
const res = await request({
  method: 'POST',
  url: 'https://api.example.com/users',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ name: 'Ada' }),
});

