## The function

```ts
export function request(options: RequestOptions): Promise<Response> {
  const {
    method = "GET",
    url,
    headers = {},
    body,
    signal,
    credentials,
    mode,
    cache,
    redirect,
    timeoutMs,
  } = options;

  const upperMethod = method.toUpperCase() as HttpMethod;
  const hasBody = upperMethod !== "GET" && upperMethod !== "HEAD";

  const init: RequestInit = {
    method: upperMethod,
    headers: { ...headers },
    signal,
    credentials,
    mode,
    cache,
    redirect,
  };

  if (hasBody && body !== undefined && body !== null) {
    init.body = body;
  }

  // Optional timeout via AbortController, combined with any caller-supplied signal.
  if (timeoutMs && timeoutMs > 0) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);

    if (signal) {
      if (signal.aborted) controller.abort(signal.reason);
      else signal.addEventListener("abort", () => controller.abort(signal.reason), { once: true });
    }

    init.signal = controller.signal;

    return fetch(url, init).finally(() => clearTimeout(timer));
  }

  return fetch(url, init);
}
```

