```ts
/**
 * Performs an HTTP request and returns the raw fetch `Response`.
 *
 * Plain-object / array bodies are JSON-encoded (and get a
 * `Content-Type: application/json` header unless one is already set).
 */
function request(options: RequestOptions): Promise<Response> {
  const { method, url, headers = {}, body } = options;

  const init: RequestInit = { method, headers: { ...headers } };

  if (body !== undefined && method !== "GET" && method !== "HEAD") {
    const isPlainJson =
      typeof body === "object" &&
      body !== null &&
      !(
        body instanceof FormData ||
        body instanceof URLSearchParams ||
        body instanceof Blob ||
        body instanceof ArrayBuffer ||
        body instanceof ReadableStream
      );

    if (isPlainJson) {
      init.body = JSON.stringify(body);
      const hasContentType = Object.keys(init.headers).some(
        (h) => h.toLowerCase() === "content-type"
      );
      if (!hasContentType) {
        (init.headers as Record<string, string>)["Content-Type"] =
          "application/json";
      }
    } else {
      init.body = body as BodyInit;
    }
  }

  return fetch(url, init);
}
```

