/**
 * Options describing a single HTTP request.
 */
export interface RequestOptions {
  /** HTTP verb to use. Defaults to "GET" when omitted. */
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "HEAD" | "OPTIONS";
  /** Absolute or relative URL to request. */
  url: string;
  /** Request headers. */
  headers?: Record<string, string>;
  /** Request payload. Ignored for GET/HEAD requests. */
  body?: string | null;
}

/**
 * Performs an HTTP request described by `options`.
 *
 * @returns A promise resolving to the fetch `Response`.
 * @throws  Rejects with the underlying network error, or with an `Error`
 *          when the server responds with a non-2xx status.
 */
export async function request(options: RequestOptions): Promise<Response> {
  const { method = "GET", url, headers = {}, body = null } = options;

  const init: RequestInit = {
    method,
    headers,
  };

  // GET/HEAD requests must not carry a body.
  if (body !== null && method !== "GET" && method !== "HEAD") {
    init.body = body;
  }

  const response = await fetch(url, init);

  if (!response.ok) {
    throw new Error(
      `Request failed: ${method} ${url} -> ${response.status} ${response.statusText}`,
    );
  }

  return response;
}
