## `RequestOptions` + `request()`

```ts
/**
 * Common HTTP verbs, with editor autocomplete while still allowing custom verbs.
 */
export type HttpMethod =
  | "GET"
  | "POST"
  | "PUT"
  | "PATCH"
  | "DELETE"
  | "HEAD"
  | "OPTIONS"
  | (string & {});

/**
 * Everything needed to describe a single HTTP request.
 */
export interface RequestOptions {
  /** HTTP verb. Defaults to "GET". */
  method?: HttpMethod;
  /** Absolute or relative URL. */
  url: string;
  /** Request headers. Plain objects, `Headers`, or entry tuples all work. */
  headers?: HeadersInit | Record<string, string | number | null | undefined>;
  /**
   * Request payload. Plain objects/arrays are serialized as JSON (and get a
   * `Content-Type: application/json` header); strings, `Blob`, `FormData`,
   * `URLSearchParams`, `ArrayBuffer`, etc. are passed through untouched.
   */
  body?: unknown;
  /** Signal to cancel the request. */
  signal?: AbortSignal;
  /** Forwarded to `fetch`. */
  credentials?: RequestCredentials;
  /** Forwarded to `fetch`. */
  cache?: RequestCache;
  /** Optional timeout in ms; aborts the request when exceeded. */
  timeoutMs?: number;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

function toHeaders(input: RequestOptions["headers"]): Headers {
  const headers = new Headers();
  if (!input) return headers;

  if (input instanceof Headers) {
    input.forEach((value, key) => headers.set(key, value));
    return headers;
  }

  if (Array.isArray(input)) {
    for (const [key, value] of input) headers.set(key, value);
    return headers;
  }

  for (const [key, value] of Object.entries(input)) {
    if (value === undefined || value === null) continue;
    headers.set(key, String(value));
  }
  return headers;
}

/** True for values that should be JSON-encoded rather than sent as-is. */
function isJsonPayload(value: unknown): value is Record<string, unknown> | unknown[] {
  if (Array.isArray(value)) return true;
  if (typeof value !== "object" || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/** Combine the caller's signal with an optional timeout signal. */
function combineSignals(signal?: AbortSignal, timeoutMs?: number): AbortSignal | undefined {
  if (!timeoutMs) return signal;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error(`Request timed out after ${timeoutMs}ms`)), timeoutMs);

  const signals = signal ? [signal, controller.signal] : [controller.signal];

  // `AbortSignal.any` exists in modern runtimes; fall back to manual linking.
  if (typeof AbortSignal.any === "function") {
    const combined = AbortSignal.any(signals);
    // Clear the timer as soon as the request settles.
    combined.addEventListener("abort", () => clearTimeout(timer), { once: true });
    return combined;
  }

  const fallback = new AbortController();
  const abort = (reason?: unknown) => fallback.abort(reason);
  for (const s of signals) {
    if (s.aborted) abort(s.reason);
    else s.addEventListener("abort", () => abort(s.reason), { once: true });
  }
  fallback.signal.addEventListener("abort", () => clearTimeout(timer), { once: true });
  return fallback.signal;
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */

/**
 * Perform an HTTP request described by `options`.
 * Resolves with the raw `Response` (non-2xx statuses resolve, they don't reject).
 */
export function request(options: RequestOptions): Promise<Response> {
  const {
    method = "GET",
    url,
    headers,
    body,
    signal,
    credentials,
    cache,
    timeoutMs,
  } = options;

  const requestHeaders = toHeaders(headers);
  const verb = method.toUpperCase();

  let requestBody: BodyInit | undefined;

  // GET/HEAD must not carry a body — `fetch` throws a TypeError if they do.
  const allowsBody = verb !== "GET" && verb !== "HEAD";

  if (body !== undefined && body !== null && allowsBody) {
    if (isJsonPayload(body)) {
      requestBody = JSON.stringify(body);
      if (!requestHeaders.has("Content-Type")) {
        requestHeaders.set("Content-Type", "application/json");
      }
    } else {
      requestBody = body as BodyInit;
    }
  }

  const init: RequestInit = {
    method,
    headers: requestHeaders,
  };

  if (requestBody !== undefined) init.body = requestBody;
  if (credentials) init.credentials = credentials;
  if (cache) init.cache = cache;

  const effectiveSignal = combineSignals(signal, timeoutMs);
  if (effectiveSignal) init.signal = effectiveSignal;

  return fetch(url, init);
}

/**
 * Convenience wrapper: performs the request and parses a JSON response.
 */
export async function requestJson<T = unknown>(options: RequestOptions): Promise<T> {
  const response = await request(options);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} ${response.statusText} for ${options.url}`);
  }
  return (await response.json()) as T;
}
```

### Usage

```ts
// Plain JSON POST
const created = await requestJson<{ id: string }>({
  method: "POST",
  url: "https://api.example.com/users",
  headers: { "Authorization": `Bearer ${token}` },
  body: { name: "Ada", role: "admin" },
});

// GET with a timeout and cancellation
const controller = new AbortController();
const res = await request({
  url: "/api/items?page=2",
  signal: controller.signal,
  timeoutMs: 5_000,
});
console.log(res.status, await res.json());

// FormData (passed through untouched, no JSON content-type set)
await request({
  method: "POST",
  url: "/upload",
  body: formData,
});
```

### Notes

- **Non-2xx doesn't reject.** `fetch` only rejects on network/CORS/abort failures. Use `requestJson` if you want a throw on bad status codes, or check `response.ok` yourself.
- **JSON detection** is based on the prototype: plain objects and arrays get serialized; `Blob`, `FormData`, `URLSearchParams`, `ArrayBuffer`, `Date`, and class instances are sent as-is (a `Date` will be stringified by `fetch`'s own `toString` — wrap it yourself if you need ISO format).
- **Headers** are normalized through the `Headers` class, so casing and duplicate handling follow the Fetch spec.
- Requires `lib: ["DOM", "ES2022"]` (or `DOM.Iterable`) in `tsconfig.json`, or `@types/node` ≥ 18 for the Node globals.
